":"payment_terms","section":"commercial","label":{"en":"Payment terms proposed","ar":"شروط الدفع المقترحة"},"type":"text","source":"supplier","envelope":"commercial","required":false},{"key":"exclusions","section":"commercial","label":{"en":"Exclusions and assumptions","ar":"الاستثناءات والافتراضات"},"type":"longtext","source":"supplier","envelope":"commercial","required":false}],"questions":[{"key":"hse_policy","section":"technical","label":{"en":"Do you have a documented HSE policy and management system?","ar":"هل لديكم سياسة وإدارة موثقة للصحة والسلامة والبيئة؟"},"type":"yesno","use":"qualification","required":true},{"key":"hse_record","section":"technical","label":{"en":"Summarise your safety record for the last three years.","ar":"لخصوا سجل السلامة لديكم خلال السنوات الثلاث الأخيرة."},"type":"text","use":"info","required":true}],"pricing":{"model":"itemized","groups":[],"lines":[]},"evaluation":{"modes":["price","weighted","manual"],"mode":"price","scale":{"min":0,"max":5},"criteria":[]},"workflow":[]}'::jsonb, '34b048391bddd22c925d804dc8cd07bf91253395a5f79a6c02c293d9668bf10d', '{"rfx","envelopes","questionnaire","line_pricing"}', 'Initial release', now());
