":"commercial","label":{"en":"Exclusions and assumptions","ar":"الاستثناءات والافتراضات"},"type":"longtext","source":"supplier","envelope":"commercial","required":false}],"questions":[{"key":"hse_policy","section":"technical","label":{"en":"Do you have a documented HSE policy and management system?","ar":"هل لديكم سياسة وإدارة موثقة للصحة والسلامة والبيئة؟"},"type":"yesno","use":"qualification","required":true},{"key":"hse_record","section":"technical","label":{"en":"Summarise your safety record for the last three years.","ar":"لخصوا سجل السلامة لديكم خلال السنوات الثلاث الأخيرة."},"type":"text","use":"info","required":true},{"key":"resources","section":"technical","label":{"en":"Describe the labour, plant and supervision you will assign.","ar":"صفوا العمالة والمعدات والإشراف التي ستخصصونها."},"type":"text","use":"scoring","required":true},{"key":"approach","section":"technical","label":{"en":"Describe your approach and work plan.","ar":"صفوا أسلوبكم وخطة العمل."},"type":"text","use":"scoring","required":true},{"key":"references","section":"technical","label":{"en":"Describe two similar projects you have delivered.","ar":"صفوا مشروعين مشابهين نفذتموهما."},"type":"text","use":"scoring","required":true}],"pricing":{"model":"milestone","groups":[{"key":"milestone","label":{"en":"Milestone","ar":"المرحلة"},"repeat":true,"inputs":[{"key":"count","label":{"en":"Number of identical stages","ar":"عدد المراحل المتماثلة"},"type":"integer","required":true,"default":1}]}],"lines":[{"key":"milestone_price","description":{"en":"Milestone: {name}","ar":"المرحلة: {name}"},"quantity":"count","unit":"STAGE","block":"LUMP_SUM","group":"milestone"}]},"evaluation":{"modes":["weighted","price","manual"],"mode":"weighted","scale":{"min":0,"max":5},"criteria":[{"key":"approach","label":{"en":"Approach and work plan","ar":"الأسلوب وخطة العمل"}},{"key":"experience","label":{"en":"Experience and references","ar":"الخبرة والمراجع"}}]},"workflow":[]}'::jsonb, 'a62e695eb20085f145d68d5f44e62f7e79